        """Form the names for the available datasets."""
        for channel in PRE_V2025_SEVIRI_WIND_CHANNELS:
            prefix = self._get_channel_prefix(channel)
            dset = self.h5f[channel]
            for measurand in dset.dtype.fields.keys():
