def _get_projection(self):
    """Get projection from the NetCDF4 attributes."""
    try:
        proj_str = self.nc.attrs["gdal_projection"]
    except TypeError:
        proj_str = self.nc.attrs["gdal_projection"].decode()

    h_multiplier = 1.0
    if "+h=1.000000" in proj_str:
        try:
            # Try to get perspective_point_height from projection_definition variable
            if "projection_definition" in self.nc:
                h = float(self.nc["projection_definition"].attrs["perspective_point_height"])
            else:
                h = float(self.nc.attrs["perspective_point_height"])
        except (KeyError, AttributeError, TypeError):
            h = 1.0

        if h != 1.0:
            h_multiplier = h
            # Replace +h=1.000000 with actual height
            proj_str = proj_str.replace("+h=1.000000", f"+h={h}")

            # Also need to scale +a=... and +b=... if they exist
            proj_str = re.sub(r'\+a=([0-9.]+)', lambda m: f"+a={float(m.group(1)) * h}", proj_str)
            proj_str = re.sub(r'\+b=([0-9.]+)', lambda m: f"+b={float(m.group(1)) * h}", proj_str)

    # Check the a/b/h units
    try:
        radius_a = proj_str.split("+a=")[-1].split()[0]
        if float(radius_a) > 10e3:
            units = "m"
            scale = 1.0
        else:
            units = "km"
            scale = 1e3
    except (IndexError, ValueError):
        # Fallback if +a is not present
        units = "m"
        scale = 1.0

    if "units" not in proj_str:
        proj_str = proj_str + " +units=" + units

    area_extent = (float(self.nc.attrs["gdal_xgeo_up_left"]) * h_multiplier / scale,
                   float(self.nc.attrs["gdal_ygeo_low_right"]) * h_multiplier / scale,
                   float(self.nc.attrs["gdal_xgeo_low_right"]) * h_multiplier / scale,
                   float(self.nc.attrs["gdal_ygeo_up_left"]) * h_multiplier / scale)

    crs = CRS.from_string(proj_str)
    return crs, area_extent

